/*
 * A365743  Triangle T(n,k) read by rows: row n has length 2*n-1, and is
 *          generated by T(1,1)=0, T(n,1)=T(n-1,1)+3, T(n,2)=T(n,1)-1, and for
 *          k>=3, T(n,k)=3*T(n-1,k-2)+1.
 * https://oeis.org/A365743
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = element T(r,k) of triangle T(n,k) defined in OEIS
 *            sequence A365743. Table rows are indexed by n, each row r has
 *            length 2*r-1. The first term is a(1) = T(1,1) = 0. The triangle
 *            is generated by T(1,1) = 0, T(n,1) = T(n-1,1)+3, T(n,2) =
 *            T(n,1)-1, T(n,k) = 3*T(n-1,k-2)+1 for k >= 3. The sequen...
 * Range:     u8 n <= 33, u16 n <= 64, u32 n <= 64, u64 n <= 64, u128 n <= 64,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>   /* malloc, free */
#include <math.h>     /* sqrt */

seq_t a(idx_t n)
{
    /* n starts at 1.  Handle out‑of‑range input as zero. */
    if (n < 1)
        return (seq_t)0;

    /* Find the row r such that r^2 >= n and (r-1)^2 < n.  */
    idx_t r = (idx_t)floor(sqrt((double)n));
    if (r * r < n)
        ++r;

    /* Column index within row r (1‑based).  */
    idx_t k = n - (r - 1) * (r - 1);

    /* Compute the triangle row by row until reaching row r.
       We build each row from the previous one.  */
    size_t prev_len = 1;
    seq_t *prev = (seq_t *)malloc(prev_len * sizeof(seq_t));
    if (!prev)
        return (seq_t)0;   /* allocation failure -> zero */
    prev[0] = (seq_t)0;     /* T(1,1) = 0 */

    for (idx_t cur = 2; cur <= r; ++cur) {
        size_t curr_len = 2 * cur - 1;
        seq_t *curr = (seq_t *)malloc(curr_len * sizeof(seq_t));
        if (!curr) {
            free(prev);
            return (seq_t)0;   /* allocation failure -> zero */
        }

        /* T(cur,1) = previous first element + 3 */
        curr[0] = prev[0] + (seq_t)3;
        /* T(cur,2) = T(cur,1) - 1 */
        curr[1] = curr[0] - (seq_t)1;

        /* For k >= 3 : T(cur,k) = 3*prev[k-2] + 1 */
        for (size_t idx = 2; idx < curr_len; ++idx) {  /* idx = k-1 */
            size_t prev_index = idx - 2;   /* k-2 in 0‑based */
            curr[idx] = prev[prev_index] * (seq_t)3 + (seq_t)1;
        }

        free(prev);
        prev = curr;
        prev_len = curr_len;
    }

    /* Retrieve the requested column value.  */
    seq_t value = prev[k - 1];

    free(prev);
    return value;
}
